// Agrupa las filas por negocio y arma los 5 parámetros de la plantilla.
//
// IMPORTANTE: los parámetros de una plantilla de WhatsApp NO pueden contener
// saltos de línea, tabulaciones ni 4 espacios seguidos (error 132000 de Meta).
// Por eso el salto de línea vive en la plantilla aprobada y aquí solo van
// valores cortos de una línea.

const ETIQUETAS = {
  ARRIENDO: 'arriendo',
  SERVICIOS: 'servicios',
  NOMINA: 'nómina',
  TRANSPORTE: 'transporte',
  MERCANCIA: 'mercancía',
  OTROS: 'otros gastos',
  VENTAS: 'ventas',
};

const dinero = (valor) => '$' + Math.round(valor).toLocaleString('es-CO');

const negocios = new Map();

for (const { json } of $input.all()) {
  if (!json.telefono) continue; // fila vacía de alwaysOutputData

  const id = json.negocio_id;
  if (!negocios.has(id)) {
    negocios.set(id, {
      negocioId: id,
      negocio: String(json.negocio),
      telefono: String(json.telefono).replace(/\D/g, ''),
      contacto: String(json.contacto || '').split(' ')[0] || 'Hola',
      desde: json.desde,
      hasta: json.hasta,
      ingresos: 0,
      gastos: 0,
      movimientos: 0,
      categoriasGasto: [],
    });
  }

  const acumulado = negocios.get(id);
  const total = Number(json.total) || 0;
  acumulado.movimientos += Number(json.movimientos) || 0;

  if (json.tipo === 'ingreso') {
    acumulado.ingresos += total;
  } else {
    acumulado.gastos += total;
    acumulado.categoriasGasto.push({ categoria: json.categoria, total });
  }
}

console.log(`[Resumen semanal] Negocios con movimientos: ${negocios.size}`);

return [...negocios.values()].map((n) => {
  const balance = n.ingresos - n.gastos;
  const mayor = n.categoriasGasto.sort((a, b) => b.total - a.total)[0];

  console.log(
    `[Resumen semanal] ${n.negocio}: ingresos ${n.ingresos}, gastos ${n.gastos}, ${n.movimientos} movimientos`,
  );

  return {
    json: {
      ...n,
      // Parámetros de la plantilla (una línea cada uno)
      p1_contacto: n.contacto,
      p2_negocio: n.negocio,
      p3_ingresos: dinero(n.ingresos),
      p4_gastos: dinero(n.gastos),
      p5_balance: (balance >= 0 ? '+' : '-') + dinero(Math.abs(balance)),
      p6_mayorGasto: mayor
        ? `${ETIQUETAS[mayor.categoria] || mayor.categoria} (${dinero(mayor.total)})`
        : 'sin gastos registrados',
      // Versión en texto plano, por si se envía dentro de la ventana de 24 h
      resumenTexto:
        `📊 Resumen del ${n.desde} al ${n.hasta}\n\n` +
        `Negocio: ${n.negocio}\n` +
        `Ingresos: ${dinero(n.ingresos)}\n` +
        `Gastos: ${dinero(n.gastos)}\n` +
        `Balance: ${dinero(balance)}\n` +
        `Movimientos: ${n.movimientos}\n` +
        (mayor
          ? `Tu mayor gasto fue ${ETIQUETAS[mayor.categoria] || mayor.categoria}: ${dinero(mayor.total)}.`
          : ''),
    },
  };
});

for (const item of $input.all()) {
  console.error('[Resumen semanal] ERROR de envío:', JSON.stringify(item.json).slice(0, 800));
}
return $input.all();
